def correct_bracketing(brackets: str):
    if not brackets:
        return False

    if len(brackets) % 2 != 0:
        return False

    if brackets[0] == '>':
        return False

    if brackets[-1] == '<':
        return False

    open_count = 0
    close_count = 0

    for char in brackets:
        if char == '<':
            open_count += 1
        elif char == '>':
            close_count += 1

        if close_count > open_count:
            return False

    if open_count != close_count:
        return False

    return True

